const themeFixtures={chip:{stocks:['a'],money60:1.4,returns:[18,12,8,5],events:3,impact:'혼합',role:'대장'},mlcc:{stocks:['h'],money60:1.3,returns:[9,7,4,4.5],events:1,impact:'미확인',role:'관련'},ai:{stocks:['d'],money60:1.1,returns:[15,10,6,4],events:2,impact:'긍정',role:'대장'},robot:{stocks:['e'],money60:.9,returns:[7,5,3,3.5],events:1,impact:'부정',role:'간판'},material:{stocks:['a','h'],money60:1.2,returns:[10,8,5,3.2],events:0,impact:'핵심 사건 없음',role:'관련'},grid:{stocks:['b'],money60:1.1,returns:[8,6,4,3],events:2,impact:'미확인',role:'대장'},cooling:{stocks:['c'],money60:1.0,returns:[6,3,2,1],events:2,impact:'미확인',role:'관련'},defense:{stocks:[],money60:.9,returns:[5,2,1,-1],events:1,impact:'혼합',role:'관련'}};
